//! Keeps the generated files of the RTL in step with [`crate::descriptors`]. After a change to a
//! descriptor, `TR_USB_WRITE=1 cargo test -p tr-usb` rewrites them.

use crate::descriptors::*;
use std::format;
use std::string::String;

const HEAD: &str = "// SPDX-License-Identifier: Apache-2.0\n// Copyright 2026 Franz Schöning, https://www.schoning.com\n//\n// GENERATED by fw/tr-usb (src/descriptors.rs) -- do not edit. Regenerate with\n";

fn rom_hex(rom: [u8; ROM_SIZE]) -> String {
    let mut s = String::new();
    s.push_str(HEAD);
    s.push_str("// `TR_USB_WRITE=1 cargo test -p tr-usb` from fw/. USB descriptor ROM for rtl/usb/usb_ep0.v,\n");
    s.push_str(&format!("// {ROM_SIZE} bytes: {ROM_SLOTS}-slot directory (offset u16, length u16, little-endian), then the\n"));
    s.push_str("// descriptors. Slot 0 device, slot 1 configuration, slots 2.. strings 0.. .\n");
    for (i, chunk) in rom.chunks(16).enumerate() {
        let bytes: std::vec::Vec<String> = chunk.iter().map(|b| format!("{b:02x}")).collect();
        s.push_str(&format!("{} // {:03x}\n", bytes.join(" "), i * 16));
    }
    s
}

fn params_vh() -> String {
    let mut s = String::new();
    s.push_str(HEAD);
    s.push_str("// `TR_USB_WRITE=1 cargo test -p tr-usb` from fw/. Values the RTL must agree on with the\n");
    s.push_str("// descriptors in rtl/usb/usb_desc_rom.hex. Included inside modules of rtl/usb/.\n");
    let p = |s: &mut String, name: &str, v: u32, what: &str| {
        s.push_str(&format!("localparam integer {name} = {v}; // {what}\n"));
    };
    p(&mut s, "USB_ROM_SIZE", ROM_SIZE as u32, "descriptor ROM bytes");
    p(&mut s, "USB_ROM_SLOTS", ROM_SLOTS as u32, "directory slots");
    p(&mut s, "USB_EP0_MAX", EP0_MAX_PACKET as u32, "control endpoint max packet");
    p(&mut s, "USB_EP_PLAY", EP_PLAY as u32, "playback: isochronous OUT 0x01, feedback IN 0x81");
    p(&mut s, "USB_EP_CAP", EP_CAP as u32, "capture: isochronous IN 0x82");
    p(&mut s, "USB_AUDIO_MAX_SAMPLES", MAX_SAMPLES_PER_USB_FRAME as u32, "most stereo samples per 1 ms frame");
    p(&mut s, "USB_AUDIO_BYTES_PER_SAMPLE", BYTES_PER_FRAME as u32, "2 channels x 2 bytes");
    p(&mut s, "USB_SAMPLE_RATE", SAMPLE_RATE, "Hz");
    p(&mut s, "USB_NUM_IFACES", NUM_INTERFACES as u32, "interfaces in configuration 1");
    p(&mut s, "USB_IF_PLAY", IF_PLAY as u32, "playback AudioStreaming interface (alt 0 off, alt 1 on)");
    p(&mut s, "USB_IF_CAP", IF_CAP as u32, "capture AudioStreaming interface (alt 0 off, alt 1 on)");
    p(&mut s, "USB_CONFIG_VALUE", CONFIG_VALUE as u32, "bConfigurationValue");
    s
}

fn check(name: &str, want: &str) {
    let path = format!("{}/../../rtl/usb/{name}", env!("CARGO_MANIFEST_DIR"));
    if std::env::var("TR_USB_WRITE").is_ok() {
        std::fs::write(&path, want).unwrap();
    }
    let have = std::fs::read_to_string(&path).unwrap_or_default().replace("\r\n", "\n");
    assert!(
        have == want,
        "{path} is out of date with fw/tr-usb/src/descriptors.rs; run `TR_USB_WRITE=1 cargo test -p tr-usb` in fw/"
    );
}

#[test]
fn generated_files_up_to_date() {
    check("usb_desc_rom.hex", &rom_hex(build_rom()));
    check("usb_desc_params.vh", &params_vh());
}
